      }
      case 'removeItem': {
        if (!isNonEmptyString(command.sku)) return fail('MISSING_FIELD', 'sku is required');
        break;
      }
      case 'pay': {
        if (!isIntAtLeast(command.amountCents, 0)) {
          return fail('BAD_AMOUNT', 'amountCents must be a non-negative integer');
        }
        break;
      }
      case 'ship': {
        if (!isNonEmptyString(command.carrier)) return fail('MISSING_FIELD', 'carrier is required');
        if (!isNonEmptyString(command.tracking)) return fail('MISSING_FIELD', 'tracking is required');
        break;
